#!/usr/bin/env bash
# Builds a Go core of @CONTRACT@ (cgo, -buildmode=c-shared / c-archive) for the
# target platforms and lays the libraries out the way the generated packages
# expect them (generated by wabi-wit-gen — DO NOT EDIT):
#
#   <out>/linux-x64/lib@LIB@.so           <out>/linux-arm64/lib@LIB@.so
#   <out>/windows-x64/@LIB@.dll
#   <out>/macos/lib@LIB@.dylib            (universal arm64 + x86_64)
#   <out>/ios/lib@LIB@.dylib              <out>/ios-simulator/lib@LIB@.dylib (arm64 + x86_64)
#   <out>/apple/@XCF@.xcframework         (static, for Swift/Xcode: iOS device + simulator)
#   <out>/android/jniLibs/<abi>/lib@LIB@.so   (arm64-v8a armeabi-v7a x86_64 x86)
#
# The Dart package (hook/build.dart, Flutter) and the NuGet package pick them up
# from <out> without further configuration.
#
#   build-native.sh <core package dir> [host|linux-x64|linux-arm64|windows-x64|macos|ios|android|all ...]
#
#   <out>   default: ../native next to this script; override with OUT=<dir>
#   needs   Go; cross targets: zig (linux, windows), macOS + Xcode (macos, ios),
#           ANDROID_NDK (android). Missing toolchains are reported and skipped.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
CORE="$(cd "${1:?usage: build-native.sh <core package dir> [targets...]}" && pwd)"
shift
OUT="${OUT:-$HERE/../native}"
mkdir -p "$OUT" && OUT="$(cd "$OUT" && pwd)"
LIB=@LIB@
export CGO_ENABLED=1
have() { command -v "$1" >/dev/null 2>&1; }
skip() { echo "SKIP $1: $2"; }
gobuild() { # mode output (GOOS/GOARCH/CC from the caller)
  (cd "$CORE" && go build -trimpath -ldflags="-s -w" -buildmode="$1" -o "$2" .)
  echo "built $2"
}
WORK="$(mktemp -d)"; trap 'rm -rf "$WORK"' EXIT
zigcc() { # zig target -> CC
  have zig || python3 -c "import ziglang" 2>/dev/null || return 1
  cat > "$WORK/zig-cc.sh" <<'ZIG'
#!/usr/bin/env bash
if command -v zig >/dev/null 2>&1; then Z=(zig); else Z=(python3 -m ziglang); fi
exec "${Z[@]}" cc -target "${ZIG_TARGET:?}" "$@"
ZIG
  chmod +x "$WORK/zig-cc.sh"
  export ZIG_TARGET="$1" CC="$WORK/zig-cc.sh"
}
host_target() {
  case "$(uname -s)-$(uname -m)" in
    Linux-x86_64) echo linux-x64 ;;
    Linux-aarch64|Linux-arm64) echo linux-arm64 ;;
    Darwin-*) echo macos ;;
    MINGW*|MSYS*|CYGWIN*) echo windows-x64 ;;
    *) echo "unknown host $(uname -s)-$(uname -m)" >&2; exit 2 ;;
  esac
}

build_linux() { # dir goarch zig-target
  mkdir -p "$OUT/$1"
  if [[ "$(host_target)" == "$1" ]]; then (GOOS=linux GOARCH=$2 gobuild c-shared "$OUT/$1/lib$LIB.so")
  elif (zigcc "$3"); then (zigcc "$3"; GOOS=linux GOARCH=$2 gobuild c-shared "$OUT/$1/lib$LIB.so")
  else skip "$1" "needs zig (pip install ziglang) to cross-compile"; fi
}

build_windows() {
  mkdir -p "$OUT/windows-x64"
  if [[ "${OS:-}" == "Windows_NT" ]]; then (GOOS=windows GOARCH=amd64 gobuild c-shared "$OUT/windows-x64/$LIB.dll")
  elif (zigcc x86_64-windows-gnu); then (zigcc x86_64-windows-gnu; GOOS=windows GOARCH=amd64 gobuild c-shared "$OUT/windows-x64/$LIB.dll")
  else skip windows-x64 "needs Windows or zig"; fi
}

build_macos() {
  if [[ "$(uname -s)" != Darwin ]]; then skip macos "needs macOS"; return; fi
  mkdir -p "$OUT/macos"
  for arch in arm64:arm64 x86_64:amd64; do
    IFS=: read -r carch goarch <<<"$arch"
    (export CC=clang CGO_CFLAGS="-arch $carch -mmacosx-version-min=11.0" CGO_LDFLAGS="-arch $carch -mmacosx-version-min=11.0"
     GOOS=darwin GOARCH=$goarch gobuild c-shared "$WORK/lib${LIB}_$carch.dylib")
  done
  lipo -create -output "$OUT/macos/lib$LIB.dylib" "$WORK/lib${LIB}_arm64.dylib" "$WORK/lib${LIB}_x86_64.dylib"
  install_name_tool -id "@rpath/lib$LIB.dylib" "$OUT/macos/lib$LIB.dylib"
}

build_ios() {
  if [[ "$(uname -s)" != Darwin ]] || ! have xcodebuild; then skip ios "needs macOS + Xcode"; return; fi
  sdk() { xcrun -sdk "$1" --show-sdk-path; }
  mkdir -p "$WORK/dev" "$WORK/sim" "$WORK/include" "$OUT/ios" "$OUT/ios-simulator" "$OUT/apple"
  local dev="-arch arm64 -miphoneos-version-min=13.0 -isysroot $(sdk iphoneos)"
  (export CC=clang CGO_CFLAGS="$dev" CGO_LDFLAGS="$dev"; GOOS=ios GOARCH=arm64 gobuild c-archive "$WORK/dev/lib$LIB.a")
  for arch in arm64:arm64 x86_64:amd64; do
    IFS=: read -r carch goarch <<<"$arch"
    local f="-arch $carch -mios-simulator-version-min=13.0 -isysroot $(sdk iphonesimulator)"
    (export CC=clang CGO_CFLAGS="$f" CGO_LDFLAGS="$f"; GOOS=ios GOARCH=$goarch gobuild c-archive "$WORK/sim/lib${LIB}_$carch.a")
  done
  lipo -create -output "$WORK/sim/lib$LIB.a" "$WORK/sim/lib${LIB}_arm64.a" "$WORK/sim/lib${LIB}_x86_64.a"
  cp "$HERE/../abi/wabi_abi.h" "$HERE/../c/$LIB.h" "$WORK/include/"
  printf 'module C@XCF@ {\n    header "wabi_abi.h"\n    header "@LIB@.h"\n    export *\n}\n' > "$WORK/include/module.modulemap"
  rm -rf "$OUT/apple/@XCF@.xcframework"
  xcodebuild -create-xcframework -library "$WORK/dev/lib$LIB.a" -headers "$WORK/include" \
    -library "$WORK/sim/lib$LIB.a" -headers "$WORK/include" -output "$OUT/apple/@XCF@.xcframework"
  # Dart native assets (Flutter) bundle a dynamic library: link the archives into one.
  dylib() { clang -dynamiclib "${@:3}" -Wl,-all_load "$2" -framework CoreFoundation -framework Security -lresolv \
    -install_name "@rpath/lib$LIB.dylib" -o "$1"; }
  dylib "$OUT/ios/lib$LIB.dylib" "$WORK/dev/lib$LIB.a" -arch arm64 -miphoneos-version-min=13.0 -isysroot "$(sdk iphoneos)"
  dylib "$OUT/ios-simulator/lib$LIB.dylib" "$WORK/sim/lib$LIB.a" -arch arm64 -arch x86_64 -mios-simulator-version-min=13.0 \
    -isysroot "$(sdk iphonesimulator)"
}

build_android() {
  local ndk="${ANDROID_NDK:-${ANDROID_NDK_HOME:-}}"
  if [[ -z "$ndk" ]]; then skip android "needs ANDROID_NDK"; return; fi
  local bin; bin=$(echo "$ndk"/toolchains/llvm/prebuilt/*/bin)
  for abi in arm64-v8a:arm64::aarch64-linux-android24 armeabi-v7a:arm:7:armv7a-linux-androideabi24 \
             x86_64:amd64::x86_64-linux-android24 x86:386::i686-linux-android24; do
    IFS=: read -r dir goarch goarm cc <<<"$abi"
    mkdir -p "$OUT/android/jniLibs/$dir"
    (export CC="$bin/$cc-clang" GOARM="$goarm"; GOOS=android GOARCH=$goarch gobuild c-shared "$OUT/android/jniLibs/$dir/lib$LIB.so")
    rm -f "$OUT/android/jniLibs/$dir/lib$LIB.h"
  done
}

build() {
  case "$1" in
    host) build "$(host_target)" ;;
    linux-x64) build_linux linux-x64 amd64 x86_64-linux-gnu.2.28 ;;
    linux-arm64) build_linux linux-arm64 arm64 aarch64-linux-gnu.2.28 ;;
    windows-x64) build_windows ;;
    macos) build_macos ;;
    ios) build_ios ;;
    android) build_android ;;
    all) for t in linux-x64 linux-arm64 windows-x64 macos ios android; do build "$t"; done ;;
    *) echo "unknown target $1 (host linux-x64 linux-arm64 windows-x64 macos ios android all)" >&2; exit 2 ;;
  esac
}
[ $# -gt 0 ] || set -- host
for t in "$@"; do build "$t"; done
find "$OUT" -name "lib$LIB.h" -delete -o -name "$LIB.h" -delete
echo "libraries in $OUT:"
(cd "$OUT" && find . \( -name '*.so' -o -name '*.dll' -o -name '*.dylib' -o -name '*.xcframework' -prune \) -print | sort)
